DELETE n FROM playerbots_names n JOIN advai_dracthyr_names a ON n.name=a.name AND n.gender=a.gender;
INSERT INTO playerbots_names (name_id,name,gender) SELECT last_id+ROW_NUMBER() OVER (ORDER BY a.name),a.name,a.gender FROM advai_dracthyr_names a CROSS JOIN (SELECT COALESCE(MAX(name_id),-1) AS last_id FROM playerbots_names) current_ids;
DROP TEMPORARY TABLE advai_dracthyr_names;
COMMIT;
